xql_query:
// ============================================================
// Rule: THM_Powershell Encoded Command Executed
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Powershell Encoded Command Executed.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1027 - Obfuscated Files or Information
// Technique: T1027.010 - Obfuscated Files or Information: Command Obfuscation

config case_sensitive = true | 
		preset = xdr_process
| filter (`actor_process_command_line` contains """powershell.exe -NoProfile -EncodedCommand""")
